      // Заготовка про уборку рабочих файлов агента. Готовой её кладём не для
      // красоты: контекст переставляется целиком на каждом ходу, и мусор в
      // PROGRESS/TASKS оплачивается заново до конца разговора.
      hygieneTitle: 'Уборка рабочих файлов агента',
      hygieneBody:
        '# {{name}}\n\n## Когда применять\n\nПеред КАЖДОЙ записью в рабочие файлы агента (`.agent/PROGRESS.md`, `TASKS.md`, заметки) и обязательно в момент, когда задача закрыта.\n\n## Правило\n\nСначала вычистить, потом дописывать. Дописанное поверх устаревшего — это контекст, который перечитывается и оплачивается на каждом следующем ходу разговора.\n\n## Порядок\n\n1. Прочитать файл целиком и отделить живое от закрытого.\n2. Из `TASKS.md` убрать сделанное; из `.agent/PROGRESS.md` — закрытые этапы, снятые вопросы, планы, которые уже не сбудутся.\n3. Каждый убранный пункт перенести ОДНОЙ строкой в `.agent/ARCHIVE.md`: дата, что сделано, где лежит результат. Архив никогда не читается целиком — он для поиска, а не для контекста.\n4. Оставить только то, что нужно, чтобы продолжить работу с нуля: незакрытое, принятые решения с их причинами, пути к коду, найденные грабли.\n5. И только теперь записать новое состояние.\n\n## Чего не делать\n\n- Не удалять единственную запись о принятом решении — переносить в архив строкой, а не стирать.\n- Не превращать `PROGRESS.md` в дневник: он отвечает на «что сделано, что осталось, чем продолжить», а не «как шла работа».\n- Не заводить рядом второй файл того же назначения — вычищать этот.\n- Не хранить в рабочих файлах секреты, токены и ключи.\n\n## Как проверить\n\nОткрыть файл и прочитать его глазами человека, который ничего о работе не знает: если по нему нельзя продолжить — вычищено слишком много, если в нём есть строки, которые уже никогда не понадобятся, — слишком мало.\n',
