        why: 'Замерено на настоящем CLI, а не прочитано в справке флага: панель просит ровно то, что CLI умеет исполнить. Нарисовать три галочки там, где исполняется одна, значило бы обещать раздельное снятие и снимать всё равно всё — человек читал бы на экране «хуки на месте» при прогоне без единого хука. Гейт промпта уходит вместе с ними по той же причине: физически он — наш хук в `~/.claude/settings.json`.',
