/**
 * Схема переводов выводится из русской версии: она источник истины.
 * Без `as const` поля имеют тип string — иначе английский перевод не прошёл бы
 * проверку типов, ведь его строки отличаются от русских литералов.
 */
export type TranslationSchema = typeof ru;
